-- 240: Corporate On-Site Training landing page. Renames category 254
--      'In House Training' -> 'Corporate On-Site Training' and renders the
--      landing (pitch + embedded form posting to corporate/index/post) via a
--      static block at its existing URL (/in-house-training.html).

UPDATE catalog_category_entity_varchar v JOIN eav_attribute ea ON ea.attribute_id=v.attribute_id AND ea.attribute_code='name' AND ea.entity_type_id=3 SET v.value='Corporate On-Site Training' WHERE v.entity_id=254 AND v.value='In House Training';

INSERT INTO cms_block (title, identifier, content, creation_time, update_time, is_active) SELECT 'Corporate On-Site Training Landing','corporate_landing',,NOW(),NOW(),1 FROM dual WHERE NOT EXISTS (SELECT 1 FROM (SELECT block_id FROM cms_block WHERE identifier='corporate_landing') t);

INSERT INTO cms_block_store (block_id, store_id) SELECT b.block_id,0 FROM cms_block b WHERE b.identifier='corporate_landing' AND NOT EXISTS (SELECT 1 FROM cms_block_store s WHERE s.block_id=b.block_id);

INSERT INTO catalog_category_entity_varchar (entity_type_id,attribute_id,store_id,entity_id,value) VALUES (3,49,0,254,'PAGE') ON DUPLICATE KEY UPDATE value='PAGE';

INSERT INTO catalog_category_entity_int (entity_type_id,attribute_id,store_id,entity_id,value) SELECT 3,50,0,254,b.block_id FROM cms_block b WHERE b.identifier='corporate_landing' LIMIT 1 ON DUPLICATE KEY UPDATE value=VALUES(value);
